#include <cuda_runtime.h>

__global__ void matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    // Define register blocking parameters
    const int BLOCK_SIZE = 32;
    const int TILE_SIZE = 4;

    // Thread indices
    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    // Declare register accumulators
    float c_val[TILE_SIZE][TILE_SIZE] = {{0.0f}};

    // Loop over tiles
    for (int t = 0; t < N; t += BLOCK_SIZE) {
        // Declare registers for A and B tiles
        float a_val[TILE_SIZE];
        float b_val[TILE_SIZE];

        // Load tiles into registers
        for (int i = 0; i < TILE_SIZE; i++) {
            int a_row = row + i * BLOCK_SIZE / TILE_SIZE;
            int a_col = t + threadIdx.x;
            if (a_row < N && a_col < N) {
                a_val[i] = A[a_row * N + a_col];
            } else {
                a_val[i] = 0.0f;
            }

            int b_row = t + threadIdx.y;
            int b_col = col + i * BLOCK_SIZE / TILE_SIZE;
